@@ -1,12 +1,43 @@
+import { readFileSync, writeFileSync, mkdirSync } from "fs";
+import { join } from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const cacheDir = ".cache";
+const cacheFile = join(cacheDir, "sessions.json");
+
+const ensureCacheDir = (): void => {
+  try {
+    mkdirSync(cacheDir, { recursive: true });
+  } catch {
+    // Directory already exists
+  }
+};
+
+const loadStore = (): Map<string, Entry> => {
+  try {
+    const data = readFileSync(cacheFile, "utf-8");
+    const obj = JSON.parse(data);
+    return new Map(Object.entries(obj) as [string, Entry][]);
+  } catch {
+    return new Map();
+  }
+};
+
+const saveStore = (store: Map<string, Entry>): void => {
+  ensureCacheDir();
+  const obj = Object.fromEntries(store);
+  writeFileSync(cacheFile, JSON.stringify(obj));
+};
+
+let store = loadStore();

 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveStore(store);
 };

